<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;
class HrEmployeeContract extends Model{protected $fillable=['employee_id','contract_number','contract_type','start_date','end_date','basic_salary','housing_allowance','transport_allowance','other_allowances','currency','status','probation_days','qiwa_contract_number','qiwa_authenticated_at','notice_period_days','notes'];protected $casts=['start_date'=>'date','end_date'=>'date','qiwa_authenticated_at'=>'datetime'];protected $appends=['gross_salary'];public function getGrossSalaryAttribute(){return (float)$this->basic_salary+(float)$this->housing_allowance+(float)$this->transport_allowance+(float)$this->other_allowances;}public function employee():BelongsTo{return $this->belongsTo(HrEmployee::class);}}